// The pigeonhole principle in its general form: m objects, n boxes,
// some box gets at least ceil(m/n).
// The two-argument size() fixes the output box at 320 x 160, so the
// declared aspect ratio 2 is exact and the reserved space cannot drift.
size(321,127);
usepackage("amsmath");
label("7 objects, 3 boxes",(0,2.4),N);
for (int i = 0; i < 3; ++i) {
  draw((3.5*i-1.7,-1.1)--(3.5*i+1.7,-1.1)--(3.5*i+1.7,1.1)--(3.5*i-1.7,1.1)--cycle, gray);
}
dot((-0.9,0.3), black+2.5pt);
dot((-0.3,0.3), black+2.5pt);
dot((0.3,0.3), black+2.5pt);
dot((2.6,0.3), black+2.5pt);
dot((3.2,0.3), black+2.5pt);
dot((3.8,0.3), black+2.5pt);
dot((6.5,0.3), black+2.5pt);
label("3 here",(-0.3,-0.5),S);
label("3 here",(3.2,-0.5),S);
label("1 here",(6.5,-0.5),S);
label("the middle count cannot go below $\\lceil 7/3 \\rceil$",(0,-1.7),S);

// The colouring invariant: each domino covers one square of each
// colour, so the difference of the two colour counts is invariant.
// The two-argument size() makes the declared ratio 1 exact.
size(245,321);
for (int i = 0; i < 8; ++i) {
  for (int j = 0; j < 8; ++j) {
    if ((i+j) % 2 == 0) fill((i,j)--(i+1,j)--(i+1,j+1)--(i,j+1)--cycle, gray);
  }
}
for (int i = 0; i <= 8; ++i) {
  draw((i,0)--(i,8),black+0.4pt);
  draw((0,i)--(8,i),black+0.4pt);
}
draw((0,0)--(1,1)--(1,0)--cycle,red+1.6pt);
draw((7,7)--(8,8)--(7,8)--cycle,red+1.6pt);
label("removed",(0.5,-0.8),S);
label("removed",(7.5,8.8),N);
label("the two removed corners carry the same colour",(4,-1.6),S);
